import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {ModeToggleComponent} from "./mode-toggle.component";
import {MODE_TOGGLE_ACTION, MODE_TOGGLE_CARD} from "./mode-toggle.types";

export * from "./mode-toggle.types";

registerCardComponent({
  name: MODE_TOGGLE_CARD,
  component: ModeToggleComponent,
  events: actionTypesToEvents(MODE_TOGGLE_ACTION),
});

import React from "react";
import {Moon, Sun} from "lucide-react";
import type {PiCardProps} from "@pihanga2/core";
import {Button} from "@/components/ui/button";
import {useTheme} from "@/components/theme-provider";
import type {ModeToggleEvents, ModeToggleProps} from "./mode-toggle.types";

export const ModeToggleComponent = (
  props: PiCardProps<ModeToggleProps, ModeToggleEvents>,
): React.ReactNode => {
  const {setTheme, theme} = useTheme();
  const {variant, className, onModeChanged, cardName} = props;

  function onClick() {
    const mode = theme === "dark" ? "light" : "dark";
    setTheme(mode);
    onModeChanged({mode});
  }

  return (
    <Button
      variant={variant ?? "ghost"}
      size="icon"
      onClick={onClick}
      className={className}
      data-pihanga={cardName}
    >
      <Sun className="h-[1.2rem] w-[1.2rem] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
      <Moon className="absolute h-[1.2rem] w-[1.2rem] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
      <span className="sr-only">Toggle theme</span>
    </Button>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";
import type {VariantT} from "../types";

export const MODE_TOGGLE_CARD = "shad/mode-toggle";
export const ModeToggle = createCardDeclaration<
  ModeToggleProps,
  ModeToggleEvents
>(MODE_TOGGLE_CARD);

export const MODE_TOGGLE_ACTION = registerActions(MODE_TOGGLE_CARD, [
  "mode_changed",
]);

export const onModeToggleChanged = createOnAction<ModeChangeEvent>(
  MODE_TOGGLE_ACTION.MODE_CHANGED,
);

// ---------------------------------------------------------------------------
// Card props & events
// ---------------------------------------------------------------------------

export type ModeToggleProps = {
  /** Visual variant of the toggle button.  Defaults to `"outline"`. */
  variant?: VariantT;
  className?: string;
};

export type ModeChangeEvent = {
  mode: "light" | "dark" | "system";
};

export type ModeToggleEvents = {
  onModeChanged: ModeChangeEvent;
};
